 32 │ /**
 33 │  * Editor state for the Data Flow page. The workflow is one tree of workplaces (`root`); `path`
 34 │  * says which inner workplace is open. All graph rules live in @reqflow/core (graph.ts) — this
 35 │  * store only applies them to the open workplace and turns errors into a visible notice.
 36 │  */
 37 │ 
 38 │ export type XY = { x: number; y: number };
 39 │ /** A React Flow connection: handle ids are port ids. */
 40 │ export type FlowConnection = {
 41 │   source: string | null;
 42 │   target: string | null;
 43 │   sourceHandle?: string | null;
 44 │   targetHandle?: string | null;
 45 │ };
 46 │ export interface Notice {
 47 │   id: number;
 48 │   tone: "info" | "error";
 49 │   message: string;
 50 │ }
 51 │ export interface Crumb {
 52 │   depth: number; // pass to goTo()
 53 │   label: string;
 54 │ }
 55 │ 
 56 │ export interface DataflowState {
 57 │   name: string;
 58 │   root: WorkflowGraph;
 59 │   path: string[]; // ids of blocks whose inner workplaces are open, outermost first
 60 │   selectedBlockIds: string[];
 61 │   selectedEdgeIds: string[];
 62 │   measured: Record<string, { width: number; height: number }>; // React Flow sizes, by block id
 63 │   notice: Notice | null;
 64 │   /** The HIL review report that is open, if any (block id + the workplace it sits on). */
 65 │   report: { blockId: string; path: string[] } | null;
 66 │   /** The Add to Car block whose thought process is open, if any. */
 67 │   reasoning: { blockId: string } | null;
 68 │   /** The Analytics block whose full-screen view is open, if any (block id + its workplace). */
 69 │   analytics: { blockId: string; path: string[] } | null;
 70 │ 
 71 │   /** Adds a block to the open workplace, selects it and returns its id. */
 72 │   addBlock(kind: PaletteBlockKind, position: XY): string;
 73 │   loadTemplate(template: WorkflowTemplate, beforeReplace?: () => boolean): boolean;
 74 │   applyNodeChanges(changes: NodeChange[]): void;
 75 │   applyEdgeChanges(changes: EdgeChange[]): void;
 76 │   /** For React Flow's isValidConnection: same rules as connect(), without side effects. */
 77 │   checkConnection(connection: FlowConnection): ConnectionCheck;
 78 │   connect(connection: FlowConnection): boolean;
 79 │   /** Deletes the selected blocks (boundary blocks excluded) and edges. */
 80 │   deleteSelection(): void;
 81 │   /** Returns an error message, or null when applied. */
 82 │   setParams(blockId: string, params: BlockParams): string | null;
 83 │   renameBlock(blockId: string, label: string): string | null;
 84 │   selectBlock(blockId: string | null): void;
 85 │   openInner(blockId: string): void;
 86 │   goTo(depth: number): void;
 87 │   /** Opens the review report of a block on the open workplace. */
 88 │   openReport(blockId: string): void;
 89 │   closeReport(): void;
 90 │   /** Opens the thought process of an Add to Car block (anywhere in the workflow). */
 91 │   openReasoning(blockId: string): void;
 92 │   closeReasoning(): void;
 93 │   /** Opens the full-screen analytics of an Analytics block on the open workplace. */
 94 │   openAnalytics(blockId: string): void;
 95 │   closeAnalytics(): void;
 96 │   /** Adds one more input to an Analytics block ("Input 2", "Input 3", …). Returns an error or null. */
 97 │   addAnalyticsInput(blockId: string): string | null;
 98 │   /** Opens the workplace at `path` and selects the block there (closes the report). */
 99 │   revealBlock(path: string[], blockId: string): void;
100 │   notify(tone: Notice["tone"], message: string): void;
101 │   dismissNotice(): void;
102 │ }
