104 │ /** Ids look like "ai-filter-3f9c1a2b": readable in logs, unique across the workflow. */
105 │ export function newBlockId(kind: PaletteBlockKind): string {
106 │   return `${kind.replace(/_/g, "-")}-${crypto.randomUUID().slice(0, 8)}`;
107 │ }
108 │ 
109 │ export function toCoreConnection(c: FlowConnection): Connection | null {
110 │   if (!c.source || !c.target || !c.sourceHandle || !c.targetHandle) return null;
111 │   return {
112 │     source: c.source,
113 │     sourcePort: c.sourceHandle,
114 │     target: c.target,
115 │     targetPort: c.targetHandle,
116 │   };
117 │ }
