119 │ /** Breadcrumb for the open workplace: "Workplace › Research › AI Filter". */
120 │ export function breadcrumbOf(root: WorkflowGraph, path: readonly string[]): Crumb[] {
121 │   const crumbs: Crumb[] = [{ depth: 0, label: "Workplace" }];
122 │   let graph = root;
123 │   path.forEach((id, i) => {
124 │     const block = graph.blocks.find((b) => b.id === id);
125 │     crumbs.push({ depth: i + 1, label: block?.label ?? id });
126 │     graph = block?.inner ?? emptyGraph();
127 │   });
128 │   return crumbs;
129 │ }
130 │ 
131 │ export const selectWorkplace = (s: DataflowState): WorkflowGraph => graphAt(s.root, s.path);
132 │ 
133 │ /** The block the inspector shows: exactly one selected block on the open workplace. */
134 │ export function selectInspectedBlock(s: DataflowState): WorkflowBlock | null {
135 │   if (s.selectedBlockIds.length !== 1) return null;
136 │   return selectWorkplace(s).blocks.find((b) => b.id === s.selectedBlockIds[0]) ?? null;
137 │ }
138 │ 
139 │ const message = (err: unknown) => (err instanceof Error ? err.message : String(err));
140 │ 
141 │ /** Readable first Zod issue, e.g. `Branches: Too small: expected array to have >=2 items`. */
142 │ function paramError(err: unknown, kind: WorkflowBlock["kind"]): string {
143 │   const issues = (err as { issues?: { path: PropertyKey[]; message: string }[] }).issues;
144 │   const issue = issues?.[0];
145 │   if (!issue) return message(err);
146 │   const key = String(issue.path[0] ?? "");
147 │   const label = isBoundaryBlockKind(kind)
148 │     ? key
149 │     : (BLOCK_SPECS[kind].params.find((p) => p.key === key)?.label ?? key);
150 │   return label ? `${label}: ${issue.message}` : issue.message;
151 │ }
