153 │ export function createDataflowStore(initial: WorkflowGraph = emptyGraph()) {
154 │   let noticeId = 0;
155 │ 
156 │   return createStore<DataflowState>()((set, get) => {
157 │     /** Runs `update` on the open workplace; on error, shows it and leaves the state unchanged. */
158 │     const edit = (update: (graph: WorkflowGraph) => WorkflowGraph): boolean => {
159 │       try {
160 │         const current = selectWorkplace(get());
161 │         const next = update(current);
162 │         if (next !== current) set({ root: updateGraphAt(get().root, get().path, () => next) });
163 │         return true;
164 │       } catch (err) {
165 │         get().notify("error", message(err));
166 │         return false;
167 │       }
168 │     };
169 │ 
170 │     return {
171 │       name: "Data Flow",
172 │       root: withSplitterWorkplaces(initial),
173 │       path: [],
174 │       selectedBlockIds: [],
175 │       selectedEdgeIds: [],
176 │       measured: {},
177 │       notice: null,
178 │       report: null,
179 │       reasoning: null,
180 │       analytics: null,
181 │ 
182 │       loadTemplate(template, beforeReplace) {
183 │         try {
184 │           const root = instantiateTemplate(template, newBlockId);
185 │           if (beforeReplace && !beforeReplace()) {
186 │             get().notify("error", "Finish or cancel the current run before loading a template.");
187 │             return false;
188 │           }
189 │           set({
190 │             name: template.name.trim(),
191 │             root,
192 │             path: [],
193 │             selectedBlockIds: [],
194 │             selectedEdgeIds: [],
195 │             measured: {},
196 │             report: null,
197 │             reasoning: null,
198 │             analytics: null,
199 │           });
200 │           get().notify(
201 │             "info",
202 │             `Loaded "${template.name}". Configure the data sources, then press Start when ready.`,
203 │           );
204 │           return true;
205 │         } catch (err) {
206 │           get().notify("error", message(err));
207 │           return false;
208 │         }
209 │       },
210 │ 
211 │       addBlock(kind, position) {
212 │         const id = newBlockId(kind);
213 │         const label = nextBlockLabel(get().root, BLOCK_SPECS[kind].label);
214 │         const block = createBlock(kind, { id, label, position });
215 │         if (edit((g) => ({ ...g, blocks: [...g.blocks, block] }))) {
216 │           set({ selectedBlockIds: [id], selectedEdgeIds: [] });
217 │         }
218 │         return id;
219 │       },
220 │ 
221 │       applyNodeChanges(changes) {
222 │         let selected = new Set(get().selectedBlockIds);
223 │         let measured = get().measured;
224 │         const removed: string[] = [];
225 │         const ok = edit((graph) => {
226 │           let g = graph;
227 │           for (const c of changes) {
228 │             if (c.type === "position" && c.position) g = moveBlock(g, c.id, c.position);
229 │             else if (c.type === "dimensions" && c.dimensions) {
230 │               measured = { ...measured, [c.id]: c.dimensions };
231 │             } else if (c.type === "select") {
232 │               selected = new Set(selected);
233 │               if (c.selected) selected.add(c.id);
234 │               else selected.delete(c.id);
235 │             } else if (c.type === "remove") removed.push(c.id);
236 │           }
237 │           return removed.length ? removeBlocks(g, removed) : g;
238 │         });
239 │         if (!ok) return;
240 │         for (const id of removed) selected.delete(id);
241 │         set({ selectedBlockIds: [...selected], measured });
242 │       },
243 │ 
244 │       applyEdgeChanges(changes) {
245 │         let selected = new Set(get().selectedEdgeIds);
246 │         const removed = changes.filter((c) => c.type === "remove").map((c) => c.id);
247 │         for (const c of changes) {
248 │           if (c.type !== "select") continue;
249 │           selected = new Set(selected);
250 │           if (c.selected) selected.add(c.id);
251 │           else selected.delete(c.id);
252 │         }
253 │         if (removed.length && !edit((g) => removeEdges(g, removed))) return;
254 │         for (const id of removed) selected.delete(id);
255 │         set({ selectedEdgeIds: [...selected] });
256 │       },
257 │ 
258 │       checkConnection(connection) {
259 │         const c = toCoreConnection(connection);
260 │         if (!c) return { ok: false, reason: "Connect an output port to an input port." };
261 │         return checkConnection(selectWorkplace(get()), c);
262 │       },
263 │ 
264 │       connect(connection) {
265 │         const c = toCoreConnection(connection);
266 │         if (!c) {
267 │           get().notify("error", "Connect an output port to an input port.");
268 │           return false;
269 │         }
270 │         return edit((g) => connectPorts(g, c));
271 │       },
272 │ 
273 │       deleteSelection() {
274 │         const graph = selectWorkplace(get());
275 │         const blocks = graph.blocks
276 │           .filter((b) => get().selectedBlockIds.includes(b.id) && !isBoundaryBlockKind(b.kind))
277 │           .map((b) => b.id);
278 │         const edges = get().selectedEdgeIds;
279 │         if (edit((g) => removeEdges(removeBlocks(g, blocks), edges))) {
280 │           set({ selectedBlockIds: [], selectedEdgeIds: [] });
281 │         }
282 │       },
283 │ 
284 │       setParams(blockId, params) {
285 │         const graph = selectWorkplace(get());
286 │         const block = graph.blocks.find((b) => b.id === blockId);
287 │         if (!block) return `Block "${blockId}" is not on this workplace`;
288 │         try {
289 │           const result = setBlockParams(graph, blockId, params);
290 │           set({ root: updateGraphAt(get().root, get().path, () => result.graph) });
291 │           const n = result.removedEdges.length;
292 │           if (n > 0) {
293 │             get().notify(
294 │               "info",
295 │               `Removed ${n} connection${n === 1 ? "" : "s"} from ports that no longer exist.`,
296 │             );
297 │           }
298 │           return null;
299 │         } catch (err) {
300 │           return paramError(err, block.kind);
301 │         }
302 │       },
303 │ 
304 │       renameBlock(blockId, label) {
305 │         try {
306 │           const graph = renameInGraph(selectWorkplace(get()), blockId, label);
307 │           set({ root: updateGraphAt(get().root, get().path, () => graph) });
308 │           return null;
309 │         } catch (err) {
310 │           return message(err);
311 │         }
312 │       },
313 │ 
314 │       selectBlock(blockId) {
315 │         set({ selectedBlockIds: blockId ? [blockId] : [], selectedEdgeIds: [] });
316 │       },
317 │ 
318 │       openInner(blockId) {
319 │         const block = selectWorkplace(get()).blocks.find((b) => b.id === blockId);
320 │         if (!block?.inner) {
321 │           get().notify("error", `"${block?.label ?? blockId}" has no inner workplace.`);
322 │           return;
323 │         }
324 │         set({ path: [...get().path, blockId], selectedBlockIds: [], selectedEdgeIds: [] });
325 │       },
326 │ 
327 │       goTo(depth) {
328 │         if (depth < 0 || depth > get().path.length) return;
329 │         set({ path: get().path.slice(0, depth), selectedBlockIds: [], selectedEdgeIds: [] });
330 │       },
331 │ 
332 │       openReport(blockId) {
333 │         const block = selectWorkplace(get()).blocks.find((b) => b.id === blockId);
334 │         if (!block) {
335 │           get().notify("error", `Block "${blockId}" is not on this workplace.`);
336 │           return;
337 │         }
338 │         set({ report: { blockId, path: [...get().path] } });
339 │       },
340 │ 
341 │       closeReport() {
342 │         set({ report: null });
343 │       },
344 │ 
345 │       openReasoning(blockId) {
346 │         const found = [...walkBlocks(get().root)].find(({ block }) => block.id === blockId);
347 │         if (found?.block.kind !== "add_to_car") {
348 │           get().notify("error", `"${found?.block.label ?? blockId}" has no thought process.`);
349 │           return;
350 │         }
351 │         set({ reasoning: { blockId } });
352 │       },
353 │ 
354 │       closeReasoning() {
355 │         set({ reasoning: null });
356 │       },
357 │ 
358 │       openAnalytics(blockId) {
359 │         const block = selectWorkplace(get()).blocks.find((b) => b.id === blockId);
360 │         if (block?.kind !== "analytics") {
361 │           get().notify("error", `"${block?.label ?? blockId}" has no analytics.`);
362 │           return;
363 │         }
364 │         set({ analytics: { blockId, path: [...get().path] } });
365 │       },
366 │ 
367 │       closeAnalytics() {
368 │         set({ analytics: null });
369 │       },
370 │ 
371 │       addAnalyticsInput(blockId) {
372 │         const block = selectWorkplace(get()).blocks.find((b) => b.id === blockId);
373 │         if (block?.kind !== "analytics") {
374 │           return `"${block?.label ?? blockId}" is not an Analytics block.`;
375 │         }
376 │         const current = Array.isArray(block.params.inputs) ? block.params.inputs.map(String) : [];
377 │         if (current.length >= MAX_ANALYTICS_INPUTS) {
378 │           return `An Analytics block has at most ${MAX_ANALYTICS_INPUTS} inputs.`;
379 │         }
380 │         let n = current.length + 1;
381 │         while (current.includes(`Input ${n}`)) n++;
382 │         return get().setParams(blockId, { ...block.params, inputs: [...current, `Input ${n}`] });
383 │       },
384 │ 
385 │       revealBlock(path, blockId) {
386 │         try {
387 │           if (!graphAt(get().root, path).blocks.some((b) => b.id === blockId)) {
388 │             throw new Error(`Block "${blockId}" no longer exists.`);
389 │           }
390 │         } catch (err) {
391 │           get().notify("error", message(err));
392 │           return;
393 │         }
394 │         set({
395 │           path: [...path],
396 │           selectedBlockIds: [blockId],
397 │           selectedEdgeIds: [],
398 │           report: null,
399 │           reasoning: null,
400 │           analytics: null,
401 │         });
402 │       },
403 │ 
404 │       notify(tone, text) {
405 │         set({ notice: { id: ++noticeId, tone, message: text } });
406 │       },
407 │ 
408 │       dismissNotice() {
409 │         set({ notice: null });
410 │       },
411 │     };
412 │   });
413 │ }
414 │ 
415 │ /** The editor's store. Lives for the whole app session, so switching tabs keeps the flow. */
416 │ export const dataflowStore = createDataflowStore();
417 │ 
418 │ /**
419 │  * `useDataflow((s) => s.path)`. Select primitives or existing objects; derive new arrays/objects
420 │  * with useMemo (zustand 5 re-renders forever on selectors that return a new object every time).
421 │  */
422 │ export function useDataflow<T>(selector: (state: DataflowState) => T): T {
423 │   return useStore(dataflowStore, selector);
424 │ }

