 4 │ /** Size of a block before React Flow has measured it (BlockNode is w-56). */
 5 │ export const DEFAULT_BLOCK_SIZE = { width: 224, height: 120 };
 6 │ const GAP = 24;
 7 │ 
 8 │ /**
 9 │  * Where to put a block added by click: the free spot nearest to `center` (top-left corner
10 │  * coordinates), searched ring by ring on a grid one block wide/tall, so blocks never stack.
11 │  */
12 │ export function findFreePosition(
13 │   graph: WorkflowGraph,
14 │   measured: DataflowState["measured"],
15 │   center: XY,
16 │ ): XY {
17 │   const { width, height } = DEFAULT_BLOCK_SIZE;
18 │   const start = { x: center.x - width / 2, y: center.y - height / 2 };
19 │   const boxes = graph.blocks.map((b) => ({
20 │     x: b.position.x,
21 │     y: b.position.y,
22 │     ...(measured[b.id] ?? DEFAULT_BLOCK_SIZE),
23 │   }));
24 │   const free = (p: XY) =>
25 │     boxes.every(
26 │       (b) =>
27 │         p.x + width + GAP <= b.x ||
28 │         b.x + b.width + GAP <= p.x ||
29 │         p.y + height + GAP <= b.y ||
30 │         b.y + b.height + GAP <= p.y,
31 │     );
32 │   const stepX = width + GAP;
33 │   const stepY = height + GAP;
34 │   for (let ring = 0; ring <= 12; ring++) {
35 │     for (let dy = -ring; dy <= ring; dy++) {
36 │       for (let dx = -ring; dx <= ring; dx++) {
37 │         if (Math.max(Math.abs(dx), Math.abs(dy)) !== ring) continue; // only this ring's cells
38 │         const p = { x: start.x + dx * stepX, y: start.y + dy * stepY };
39 │         if (free(p)) return p;
40 │       }
41 │     }
42 │   }
43 │   return start; // a very crowded workplace: overlap rather than fail
44 │ }
