21 │ /** Workplace graph → React Flow nodes. Sizes come from the store so nodes don't re-measure. */
22 │ export function toFlowNodes(
23 │   graph: WorkflowGraph,
24 │   selectedIds: readonly string[],
25 │   measured: DataflowState["measured"],
26 │ ): BlockFlowNode[] {
27 │   const selected = new Set(selectedIds);
28 │   return graph.blocks.map((block) => {
29 │     const boundary = isBoundaryBlockKind(block.kind);
30 │     return {
31 │       id: block.id,
32 │       type: boundary ? "boundary" : "block",
33 │       position: block.position,
34 │       data: {
35 │         block,
36 │         ports: blockPorts(block),
37 │         spec: boundary ? null : BLOCK_SPECS[block.kind as keyof typeof BLOCK_SPECS],
38 │       },
39 │       selected: selected.has(block.id),
40 │       measured: measured[block.id],
41 │       deletable: !boundary,
42 │     };
43 │   });
44 │ }
