 17 │ const previewLimit = 20_000;
 18 │ const previewMaxDepth = 32;
 19 │ const previewMaxNodes = 5_000;
 20 │ const previewTruncated = "\nSource preview truncated; full original available through export.";
 21 │ 
 22 │ function rawPrefixEnd(text: string, limit: number): number {
 23 │   let end = Math.min(text.length, limit);
 24 │   if (end > 0 && end < text.length) {
 25 │     const last = text.charCodeAt(end - 1);
 26 │     const next = text.charCodeAt(end);
 27 │     if (
 28 │       (last >= 0xd800 && last <= 0xdbff && next >= 0xdc00 && next <= 0xdfff) ||
 29 │       (last === 13 && next === 10)
 30 │     )
 31 │       end--;
 32 │   }
 33 │   return end;
 34 │ }
 35 │ 
 36 │ /** Cut serialized text only between complete escape tokens and Unicode code points. */
 37 │ function jsonPrefixEnd(text: string, limit: number): number {
 38 │   const end = rawPrefixEnd(text, limit);
 39 │   let position = 0;
 40 │   while (position < end) {
 41 │     const code = text.charCodeAt(position);
 42 │     const next = text.charCodeAt(position + 1);
 43 │     const width =
 44 │       code === 92
 45 │         ? text.startsWith("\\r\\n", position)
 46 │           ? 4
 47 │           : text[position + 1] === "u"
 48 │             ? 6
 49 │             : 2
 50 │         : code >= 0xd800 && code <= 0xdbff && next >= 0xdc00 && next <= 0xdfff
 51 │           ? 2
 52 │           : 1;
 53 │     if (position + width > end) break;
 54 │     position += width;
 55 │   }
 56 │   return position;
 57 │ }
